import{_ as t,o as i,c as e,a5 as s}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":".NET 编译与 CLR：从源码到执行","description":"本页回答三个问题：C# 源码如何变成可执行的程序集，CLR（Common Language Runtime）在运行时承担哪些职责，托管代码与非托管代码的边界在哪里。这是理解 GC、JIT 和类型布局的前提。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"csharp/02-dotnet-runtime/chapter-01-compilation-clr.md","filePath":"csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"}'),l={name:"csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"};function r(n,a,c,d,p,h){return i(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="net-编译与-clr-从源码到执行" tabindex="-1" data-src-line="2" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">.NET 编译与 CLR：从源码到执行 <a class="header-anchor" href="#net-编译与-clr-从源码到执行" aria-label="Permalink to &quot;.NET 编译与 CLR：从源码到执行&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">本页回答三个问题：C# 源码如何变成可执行的程序集，CLR（Common Language Runtime）在运行时承担哪些职责，托管代码与非托管代码的边界在哪里。这是理解 GC、JIT 和类型布局的前提。</p><h2 id="_1-编译流程" tabindex="-1" data-src-line="6" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">1. 编译流程 <a class="header-anchor" href="#_1-编译流程" aria-label="Permalink to &quot;1. 编译流程&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">C# 源码经过编译器（Roslyn）编译为中间语言（IL），连同元数据一起打包为程序集（assembly，通常是 <code>.dll</code> 或 <code>.exe</code> 文件）：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C# 源码 → 编译器（Roslyn）→ IL + 元数据 → 程序集（.dll）</span></span></code></pre></div><p data-src-line="14" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">一个简单方法编译成 IL 后长这样。用 <code>dotnet-ildasm</code> 查看程序集即可看到这份 IL：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span></span></code></pre></div><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.method static int32 Add(int32 a, int32 b) cil managed</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    .maxstack 2</span></span>
<span class="line"><span>    IL_0000: ldarg.0     // 加载参数 a</span></span>
<span class="line"><span>    IL_0001: ldarg.1     // 加载参数 b</span></span>
<span class="line"><span>    IL_0002: add         // a + b</span></span>
<span class="line"><span>    IL_0003: ret         // 返回结果</span></span>
<span class="line"><span>}</span></span></code></pre></div><p data-src-line="31" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><code>ldarg</code> 加载参数、<code>add</code> 相加、<code>ret</code> 返回——IL 是基于栈的指令序列，运行时再把它 JIT 成本机机器码。</p><p data-src-line="33" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">程序集不是可独立运行的原生代码，而是运行时可以加载和执行的托管格式。它包含：</p><ul data-src-line="35" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><li data-src-line="35" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><strong>IL</strong>：平台无关的指令序列，描述方法体逻辑。</li><li data-src-line="36" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><strong>元数据</strong>：类型、成员、引用的声明信息，供反射和工具读取。</li><li data-src-line="37" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><strong>资源与程序集清单</strong>：版本、依赖、入口点等。</li></ul><p data-src-line="39" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">执行时，运行时加载程序集，把 IL 交给 JIT 编译为机器码（见<a href="./chapter-04-jit-aot.html">JIT 与 AOT</a>）。</p><h2 id="_2-clr-承担什么" tabindex="-1" data-src-line="41" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">2. CLR 承担什么 <a class="header-anchor" href="#_2-clr-承担什么" aria-label="Permalink to &quot;2. CLR 承担什么&quot;">​</a></h2><p data-src-line="43" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">CLR 是 .NET 的托管执行环境，对应 Java 的 JVM。它提供的核心能力：</p><table tabindex="0"><thead data-src-line="45" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><tr data-src-line="45" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><th style="text-align:left;">职责</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="47" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><tr data-src-line="47" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><td style="text-align:left;">类型系统</td><td style="text-align:left;">加载类型、解析引用、执行类型安全规则</td></tr><tr data-src-line="48" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><td style="text-align:left;">JIT 编译</td><td style="text-align:left;">把 IL 编译为当前 CPU 的机器码</td></tr><tr data-src-line="49" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><td style="text-align:left;">垃圾回收</td><td style="text-align:left;">自动回收托管堆内存（见<a href="./chapter-03-gc.html">GC</a>）</td></tr><tr data-src-line="50" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><td style="text-align:left;">异常处理</td><td style="text-align:left;">管理异常的抛出与栈展开</td></tr><tr data-src-line="51" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><td style="text-align:left;">线程与异步</td><td style="text-align:left;">提供线程池、<code>Task</code> 调度等基础设施</td></tr><tr data-src-line="52" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><td style="text-align:left;">互操作</td><td style="text-align:left;">通过 P/Invoke 调用非托管代码（见<a href="./chapter-05-unmanaged-interop.html">非托管互操作</a>）</td></tr></tbody></table><p data-src-line="54" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">「托管代码」指运行在 CLR 控制之下的代码：它的内存、类型和异常都由运行时管理。「非托管代码」是脱离 CLR 的原生代码（C/C++ 库、操作系统 API），通过互操作层调用。</p><h2 id="_3-托管执行的含义" tabindex="-1" data-src-line="56" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">3. 托管执行的含义 <a class="header-anchor" href="#_3-托管执行的含义" aria-label="Permalink to &quot;3. 托管执行的含义&quot;">​</a></h2><p data-src-line="58" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">托管执行带来的关键变化是：代码运行在运行时的约束下，而非直接面对操作系统。</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> List</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> };</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">list.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p data-src-line="65" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">这段代码运行时，<code>new List&lt;int&gt;</code> 由运行时在托管堆上分配，<code>Add</code> 通过 JIT 编译后的机器码执行，<code>list</code> 不再被引用后由 GC 回收。开发者不管理内存，但也因此失去对内存布局和释放时机的直接控制。</p><p data-src-line="67" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">托管执行不是零成本。它带来 JIT 编译的启动开销、GC 的暂停、边界检查等成本，换来的是内存安全、类型安全和更高的开发效率。这个权衡在<a href="./../01-csharp-language/chapter-01-why-csharp.html">认识 .NET 与 C#</a>中已展开。</p><h2 id="_4-程序集的加载" tabindex="-1" data-src-line="69" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">4. 程序集的加载 <a class="header-anchor" href="#_4-程序集的加载" aria-label="Permalink to &quot;4. 程序集的加载&quot;">​</a></h2><p data-src-line="71" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">运行时按需加载程序集。当类型第一次被使用时，运行时定位并加载其所在程序集，解析依赖，完成类型初始化。程序集有版本和强名称（可选），运行时依据这些信息避免加载冲突。</p><p data-src-line="73" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">默认情况下 .NET 应用框架依赖的程序集（<code>System.*</code>）随运行时提供，应用自身的程序集和第三方包则随应用部署。.NET 5 之后统一为跨平台的 .NET，不再区分 .NET Framework 的 GAC（全局程序集缓存）模型。</p><h2 id="_5-后续阅读" tabindex="-1" data-src-line="75" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">5. 后续阅读 <a class="header-anchor" href="#_5-后续阅读" aria-label="Permalink to &quot;5. 后续阅读&quot;">​</a></h2><ul data-src-line="77" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><li data-src-line="77" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><a href="./chapter-02-type-layout-memory.html">类型布局与内存</a>解释托管对象在堆上的布局。</li><li data-src-line="78" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><a href="./chapter-03-gc.html">GC</a>解释托管堆如何回收内存。</li><li data-src-line="79" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><a href="./chapter-04-jit-aot.html">JIT 与 AOT</a>解释 IL 如何变为机器码。</li><li data-src-line="80" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><a href="./chapter-05-unmanaged-interop.html">非托管互操作</a>解释托管与非托管的边界。</li></ul><blockquote data-src-line="82" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md"><p data-src-line="82" data-src-file="csharp/02-dotnet-runtime/chapter-01-compilation-clr.md">本页的技术边界按 .NET 10 / C# 14 核对；.NET 5 起统一跨平台运行时，此前的 .NET Framework 使用独立的 GAC 模型。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/" target="_blank" rel="noreferrer">.NET 文档</a>、<a href="https://learn.microsoft.com/en-us/dotnet/standard/clr" target="_blank" rel="noreferrer">通用语言运行时</a>。</p></blockquote>`,27)])])}const k=t(l,[["render",r]]);export{m as __pageData,k as default};
